(() => {
  'use strict';
  if(window.__franklinConnectLoaded)return;window.__franklinConnectLoaded=true;
  const PHOTO='https://cdn.corenexis.com/f/dJ4k8HeoKK9.jpeg',reduced=matchMedia('(prefers-reduced-motion: reduce)');let active=false,timers=[],audio=null;
  if(!document.querySelector('link[data-franklin-connect]')){const l=document.createElement('link');l.rel='stylesheet';l.href='franklin-connect.css?v=20261027b';l.dataset.franklinConnect='true';document.head.append(l);}
  const clear=()=>{timers.forEach(clearTimeout);timers=[];try{audio?.stop()}catch{}audio=null;};
  function tone(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),master=ctx.createGain();master.gain.setValueAtTime(.0001,ctx.currentTime);master.gain.exponentialRampToValueAtTime(.032,ctx.currentTime+.06);master.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+1.45);master.connect(ctx.destination);const osc=ctx.createOscillator(),g=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(196,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(294,ctx.currentTime+1.3);g.gain.value=.4;osc.connect(g);g.connect(master);osc.start();osc.stop(ctx.currentTime+1.5);audio=osc;}catch{}}
  function ensure(){let v=document.querySelector('.franklin-connect');if(v)return v;v=document.createElement('div');v.className='franklin-connect';v.setAttribute('aria-hidden','true');v.innerHTML=`<div class="franklin-connect-inner"><button class="franklin-connect-cancel" type="button">Cancel</button><div class="franklin-connect-avatar"><img src="${PHOTO}" alt="Franklin"></div><div class="franklin-connect-kicker">ASSISTANT CHANNEL</div><strong>Connecting to Franklin</strong><span class="franklin-connect-status">Opening secure local assistant…</span><div class="franklin-connect-track"><i></i></div><small class="franklin-connect-percent">0%</small></div>`;document.querySelector('.ask-franklin-panel')?.append(v);v.querySelector('.franklin-connect-cancel')?.addEventListener('click',cancel);return v;}
  function cancel(){if(!active)return;active=false;clear();const v=ensure();v.classList.remove('is-active');v.setAttribute('aria-hidden','true');document.querySelector('.ask-franklin-close')?.click();window.gtavHaptics?.trigger?.('soft');}
  function start(){if(active)return;active=true;clear();const v=ensure(),bar=v.querySelector('.franklin-connect-track i'),pct=v.querySelector('.franklin-connect-percent'),status=v.querySelector('.franklin-connect-status');v.classList.add('is-active');v.setAttribute('aria-hidden','false');bar.style.width='0%';pct.textContent='0%';tone();window.gtavHaptics?.trigger?.('soft');const duration=reduced.matches?450:5000,startAt=performance.now();const tick=now=>{if(!active)return;let p=Math.min(1,(now-startAt)/duration);p=1-Math.pow(1-p,2.15);const n=Math.min(100,Math.round(p*100));bar.style.width=n+'%';pct.textContent=n+'%';status.textContent=n<38?'Opening secure local assistant…':n<76?'Loading project knowledge…':'Franklin is ready…';if(n<100)requestAnimationFrame(tick);};requestAnimationFrame(tick);timers.push(setTimeout(()=>{if(!active)return;active=false;clear();v.classList.add('is-complete');window.gtavHaptics?.trigger?.('success');setTimeout(()=>{v.classList.remove('is-active','is-complete');v.setAttribute('aria-hidden','true');},reduced.matches?0:240);},duration+80));}
  document.addEventListener('click',e=>{const b=e.target instanceof Element?e.target.closest('.ask-franklin-launcher'):null;if(!b)return;setTimeout(()=>{if(document.querySelector('.ask-franklin-panel.is-open'))start();},40);});window.FranklinConnect={start,cancel};
})();